      `RATE_SET sheet=${sheet} by=uma grade=A rate=10.00`,
      `RATE_SET sheet=${sheet} by=uma grade=B rate=20.00`,
      `PERSON_ADDED sheet=${sheet} by=uma name=Ada grade=A`,
      `ROLLUP sheet=${sheet} by=uma person=Ada claimed=0.00 due-total=0.00 overdue-total=0.00`,
      `PERSON_ADDED sheet=${sheet} by=uma name=Ben grade=B`,
      `ROLLUP sheet=${sheet} by=uma person=Ben claimed=0.00 due-total=0.00 overdue-total=0.00`,
      `SETTING_CHANGED sheet=${sheet} by=uma key=proof-threshold value=1.50`,
      `SETTING_CHANGED sheet=${sheet} by=uma key=proof-threshold-B value=5.00 from=2026-03-05`,
      `CLAIM_ADDED sheet=${sheet} by=uma person=Ada amount=20.00 date=2026-03-10`,
      `CLAIM_ADDED sheet=${sheet} by=uma person=Ben amount=20.00 date=2026-03-10`,
      `CLAIM_ADDED sheet=${sheet} by=uma person=Ben amount=30.00 date=2026-03-01`,
      `CLAIM_ADDED sheet=${sheet} by=uma person=Ben amount=10.00 date=2026-03-10`,
      `CLAIM_OPENED sheet=${sheet} by=uma person=Ada amount=20.00 date=2026-03-10 number=1`,
      `ROLLUP sheet=${sheet} by=uma person=Ada claimed=20.00 due-total=2.00 overdue-total=0.00`,
      `TOTALS sheet=${sheet} by=uma claimed-total=20.00 due-total=2.00 overdue-total=0.00`,
      `CLAIM_OPENED sheet=${sheet} by=uma person=Ben amount=20.00 date=2026-03-10 number=2`,
      `ROLLUP sheet=${sheet} by=uma person=Ben claimed=20.00 due-total=4.00 overdue-total=0.00`,
      `TOTALS sheet=${sheet} by=uma claimed-total=40.00 due-total=6.00 overdue-total=0.00`,
      `CLAIM_OPENED sheet=${sheet} by=uma person=Ben amount=30.00 date=2026-03-01 number=3`,
      `ROLLUP sheet=${sheet} by=uma person=Ben claimed=50.00 due-total=10.00 overdue-total=0.00`,
      `TOTALS sheet=${sheet} by=uma claimed-total=70.00 due-total=12.00 overdue-total=0.00`,
      `CLAIM_OPENED sheet=${sheet} by=uma person=Ben amount=10.00 date=2026-03-10 number=4`,
      `ROLLUP sheet=${sheet} by=uma person=Ben claimed=60.00 due-total=12.00 overdue-total=0.00`,
      `TOTALS sheet=${sheet} by=uma claimed-total=80.00 due-total=14.00 overdue-total=0.00`,
      `CLAIM_SETTLED sheet=${sheet} by=vic person=Ben amount=20.00 date=2026-03-10 number=2 due=4.00`,
      `CLAIM_SETTLED sheet=${sheet} by=vic person=Ben amount=30.00 date=2026-03-01 number=3 due=6.00`,
      `CLAIM_SETTLED sheet=${sheet} by=vic person=Ben amount=10.00 date=2026-03-10 number=4 due=2.00`,
      `SETTING_CHANGED sheet=${sheet} by=uma key=proof-threshold-B value= from=2026-03-05`
    ]);
  });
  test("proof threshold per grade scenario 1", { tag: '@functionality' }, async ({ browser }) => {
