test("proof threshold per grade scenario 1", { tag: '@functionality' }, async ({ browser }) => {
  const sheet = ui.sheetId();
  const pg_uma = await ui.userPage(browser, "uma", sheet);
  await ui.setToday(pg_uma, "2026-03-20");
  expect(await ui.setRole(pg_uma, "wes", "steward")).toBe(true);
  await ui.setSetting(pg_uma, "clerk-limit", "1.50");
  await ui.setSetting(pg_uma, "floor", "2.00");
  await ui.setSetting(pg_uma, "terms", "10");
  await ui.setSetting(pg_uma, "late-pct", "10.00");
  await ui.setSetting(pg_uma, "perm-void", "clerk");
  expect(await ui.addHoliday(pg_uma, "2026-03-24")).toBe(true);
  expect(await ui.addHoliday(pg_uma, "2026-03-13")).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "A", "pct": "10.00"})).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "B", "pct": "5.00"})).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "C", "pct": "10.00"})).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "A", "pct": "10.00", "from": "2026-03-10", "to": "2026-03-12"})).toBe(true);
  expect(await ui.generatePeriods(pg_uma, "2026-02-01", "2026-04-30")).toBe(3);
  const p_ben = ui.must(await ui.addPerson(pg_uma, {"name": "Ben", "grade": "B"}));
  const p_ada = ui.must(await ui.addPerson(pg_uma, {"name": "Ada", "grade": "A"}));
  const p_cam = ui.must(await ui.addPerson(pg_uma, {"name": "Cam", "grade": "C"}));
  expect(await ui.bulkGrade(pg_uma, [p_ben, p_ada], {"grade": "C"})).toBe(2);
  const c_cam_0 = ui.must(await ui.addClaim(pg_uma, p_cam, {"amount": "12.50", "date": "2026-03-09", "note": "n", "tags": " c "}));
  expect(await ui.periodAction(pg_uma, "2026-03", "soft-close")).toBe(true);
  const pg_wes = await ui.userPage(browser, "wes", sheet);
  expect(await ui.periodAction(pg_wes, "2026-03", "reopen")).toBe(true);
  expect(await ui.claimAction(pg_wes, c_cam_0, "void")).toBe(false);
  expect(await ui.addHoliday(pg_wes, "2026-03-27")).toBe(true);
  const c_ben_0 = ui.must(await ui.addClaim(pg_wes, p_ben, {"amount": "12.50", "date": "2026-02-25", "ref": "R-1"}));
  await ui.refresh(pg_wes);
  const c_cam_1 = ui.must(await ui.addClaim(pg_wes, p_cam, {"amount": "10.25", "date": "2026-02-25"}));
  const pg_vic = await ui.userPage(browser, "vic", sheet);
  expect(await ui.statement(pg_vic, p_ben)).toBe(true);
  expect(await ui.editClaim(pg_vic, c_cam_0, {"amount": "3.33"})).toBe(true);
  await ui.refresh(pg_wes);
  expect(await ui.reassign(pg_wes, c_cam_0, "Ada")).toBe(true);
  expect(await ui.pasteClaims(pg_wes, "Ben,1.00,,paste")).toBe(1);
  const c_ben_1 = await ui.claimAt(pg_wes, p_ben, 1);
  expect(await ui.pasteClaims(pg_wes, "Ada,12.50,2026-03-15,\nCam,7.77,2026-04-02,a, b")).toBe(2);

